import React, { useState } from 'react';
import NavTop from '../components/NavTop';

const MessagingPortal = () => {
  const [messages, setMessages] = useState([
    { text: "Hello! Thank you for booking Azure Heights Villa. I'm Eleni, your host. I've just received your confirmation.", isSent: false },
    { text: "Hi Eleni! We're so excited for our stay. I just wanted to confirm if early check-in at 2 PM might be possible?", isSent: true }
  ]);
  const [input, setInput] = useState('');

  const handleSend = () => {
    if (!input.trim()) return;
    setMessages([...messages, { text: input, isSent: true }]);
    setInput('');
  };

  return (
    <div className="h-screen overflow-hidden flex flex-col">
      <NavTop role="tenant" />
      <main className="flex-grow pt-20 pb-8 px-margin-mobile md:px-margin-desktop max-w-container-max mx-auto w-full h-full overflow-hidden">
        <div className="glass-panel w-full h-full rounded-[24px] shadow-2xl flex overflow-hidden">
          <aside className="w-full md:w-[380px] border-r border-outline-variant/30 flex flex-col bg-white/40">
            <div className="p-6 border-b border-outline-variant/20">
              <h1 className="text-2xl font-bold mb-4">Messages</h1>
              <input className="w-full pl-4 pr-4 py-2.5 bg-white/50 border border-outline-variant/30 rounded-xl" placeholder="Search conversations..." />
            </div>
            <div className="flex-grow overflow-y-auto custom-scrollbar">
              <div className="p-4 bg-primary/5 border-l-4 border-primary flex gap-4 cursor-pointer">
                <img src="https://lh3.googleusercontent.com/aida-public/AB6AXuCeK5UVisi3xmg4SlRdWlUhK2YeT-PEqFxl0LaMbGHn_uGdOLQKqZ5YELQJX9cblkytefrGd_DurUU5MJM7Dlv5Fq3gpP3qz1BqvtcC3dOi-q97UEJ5Y7YnQHR1sR0S1S5BPIOmhGdaJF0PD7RoXc0VENjcVloND5d-S0xlbY2h4P6uTEREHlQAkHn9Ltcq-v_3wfHltaXr1vHmApsw3ckKXrCtx8ujndmTlr3bK8Fma2LisWslY7k1BkDA3S287JTOd8WFMS8ae6k" className="w-14 h-14 rounded-xl object-cover" alt="Host"/>
                <div className="min-w-0">
                  <div className="flex justify-between items-start mb-1"><span className="font-bold truncate">Eleni - Azure Heights Villa</span></div>
                  <p className="text-sm text-secondary truncate">The check-in instructions are...</p>
                </div>
              </div>
            </div>
          </aside>
          <section className="flex-grow flex flex-col bg-white/10">
            <header className="h-20 px-6 border-b border-outline-variant/30 flex items-center justify-between bg-white/50 backdrop-blur-md">
              <div className="flex items-center gap-4">
                <img src="https://lh3.googleusercontent.com/aida-public/AB6AXuC-xrTlnIJIts8syEX6wp_-N9w9L8zI5Sc0Rya5WP9rjC5mWMX9vzX0eGsxRTapaLU56lVx97ZHd3cauT8-ZFBvy0KxEqTspye8gqUCCBbTQSIOxHWV3zh4HTtVBPu4C9xsWFeHWT5TWfWekWGMwjFzpd5Gbi-zhWZtAnAeIcGXmNLO9llMfh2eBwUDYkCLCqTQyhXjYv6qrGNgnF8UHOn7HZyijrwDSTSaQZna8wl1aR-NMK_0iPZoMFf1njGSrmHvgd_of_fU1As" className="w-10 h-10 rounded-full object-cover" alt="Host"/>
                <div><h2 className="font-bold">Eleni</h2><p className="text-xs text-primary font-bold">Azure Heights Villa • Host</p></div>
              </div>
            </header>
            <div className="flex-grow p-6 overflow-y-auto custom-scrollbar flex flex-col gap-6">
              {messages.map((m, i) => (
                <div key={i} className={`flex gap-3 max-w-[80%] ${m.isSent ? 'ml-auto flex-row-reverse' : ''}`}>
                  <div className={`${m.isSent ? 'message-bubble-sent' : 'message-bubble-received'} p-4 shadow-sm text-sm`}>{m.text}</div>
                </div>
              ))}
            </div>
            <footer className="p-6 bg-white/60 border-t border-outline-variant/30">
              <div className="flex items-center gap-3 bg-white border border-outline-variant/40 p-2 rounded-2xl">
                <button className="p-2 text-secondary"><span className="material-symbols-outlined">add_circle</span></button>
                <input value={input} onChange={e => setInput(e.target.value)} onKeyPress={e => e.key === 'Enter' && handleSend()} className="flex-grow border-none focus:ring-0 text-sm" placeholder="Type your message..." />
                <button onClick={handleSend} className="bg-primary text-white w-10 h-10 rounded-xl flex items-center justify-center"><span className="material-symbols-outlined" style={{fontVariationSettings: "'FILL' 1"}}>send</span></button>
              </div>
            </footer>
          </section>
        </div>
      </main>
    </div>
  );
};

export default MessagingPortal;
